const express = require('express');
const helmet = require('helmet');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.hidePoweredBy());

// Limit request size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// Input validation middleware for any query parameters
const validateQuery = [
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }
    next();
  }
];

// Rate limiting (placeholder - would use express-rate-limit in practice)
let requestCount = {};
const RATE_LIMIT = 100; // requests per hour
const WINDOW_MS = 60 * 60 * 1000; // 1 hour

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  if (!requestCount[ip]) {
    requestCount[ip] = { count: 1, firstRequest: now };
  } else {
    // Clean up old request records
    if (now - requestCount[ip].firstRequest > WINDOW_MS) {
      requestCount[ip] = { count: 1, firstRequest: now };
    } else {
      requestCount[ip].count++;

      if (requestCount[ip].count > RATE_LIMIT) {
        return res.status(429).json({ 
          error: 'Rate limit exceeded. Please try again later.' 
        });
      }
    }
  }
  next();
});

app.get('/health', (req, res) => {
  // Explicitly avoid exposing any sensitive information
  res.json({ status: 'ok' });
});

app.get('/users', validateQuery, (req, res) => {
  try {
    // In a real app, this would come from a database with proper access controls
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ];

    // Apply pagination if requested
    const limit = parseInt(req.query.limit) || 10;
    const page = parseInt(req.query.page) || 1;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const results = users.slice(startIndex, endIndex);

    res.json({
      data: results,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't expose internal error details to clients
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  // In production, this should be at info or warn level only
  if (process.env.NODE_ENV !== 'production') {
    console.log('Environment:', process.env.NODE_ENV || 'development');
  }
});

module.exports = app;

