    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Never expose sensitive fields like passwords or tokens
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
