const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Check for unexpected query parameters
  const validParams = ['limit', 'offset', 'sort'];
  const invalidParams = Object.keys(req.query).filter(param => !validParams.includes(param));

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: `Invalid query parameters: ${invalidParams.join(', ')}`,
      validParams: validParams
    });
  }

  // Validate parameter values
  if (req.query.limit) {
    const limit = parseInt(req.query.limit);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Limit must be a number between 1 and 100'
      });
    }
  }

  if (req.query.offset) {
    const offset = parseInt(req.query.offset);
    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Offset must be a non-negative number'
      });
    }
  }

  next();
};

// Enhanced health check with rate limiting awareness
app.get('/health', validateQueryParams, (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// Users endpoint with input validation and sanitization
app.get('/users', validateQueryParams, (req, res) => {
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply limit if specified
  if (req.query.limit) {
    const limit = parseInt(req.query.limit);
    const offset = parseInt(req.query.offset) || 0;
    users = users.slice(offset, offset + limit);
  }

  res.json(users);
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle different error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation failed',
      message: error.message
    });
  }

  if (error.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Authentication required',
      message: error.message
    });
  }

  // Generic error response
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Security features enabled: helmet, cors, input validation`);
});

module.exports = app;

