const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult, param } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(helmet.hidePoweredBy()); // Remove X-Powered-By header

// CORS configuration - restrict to trusted domains in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://your-trusted-domain.com'] 
    : true // Allow all in development
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Body parsing with limits to prevent denial of service
app.use(express.json({
  limit: '10kb', // Limit JSON payload size
  strict: true // Only parse objects and arrays
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' // Limit urlencoded payload size
}));

// Input validation middleware for users route
const validateUserId = param('id')
  .isInt({ min: 1 })
  .withMessage('User ID must be a positive integer');

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak stack traces in production
  const errorResponse = {
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message,
    timestamp: new Date().toISOString()
  };

  if (err.status) {
    res.status(err.status).json(errorResponse);
  } else {
    res.status(500).json(errorResponse);
  }
});

// Health check route (no input validation needed)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Users route with proper response structure
app.get('/users', [
  // Add validation if query parameters are used
  // For example, if supporting pagination:
  // query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  // query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
], (req, res, next) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const error = new Error('Validation failed');
      error.status = 400;
      error.data = errors.array();
      return next(error);
    }

    // In a real application, this would fetch from a database
    // with proper error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users,
      count: users.length,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res, next) => {
  const error = new Error(`Route ${req.originalUrl} not found`);
  error.status = 404;
  next(error);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

