const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');
const app = express();

// Security middleware
app.use(helmet()); // Security HTTP headers

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});

app.use(limiter);

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS || '*',
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// Middleware for parsing JSON
app.use(express.json({ limit: '10kb' })); // Limit request size
app.use(express.urlencoded({ extended: true }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - IP: ${req.ip}`);
  next();
});

// Input validation middleware for /users route
const validateUsersQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a positive integer'),
  query('search')
    .optional()
    .isString()
    .trim()
    .escape()
    .isLength({ max: 50 })
    .withMessage('Search query too long'),
];

// Health check with error handling
app.get('/health', [
  rateLimit({
    windowMs: 60 * 1000, // 1 minute
    max: 60, // 60 requests per minute
    message: 'Too many requests to health check',
  })
], (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validateUsersQuery, (req, res) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        status: 'error', 
        message: 'Validation failed',
        errors: errors.array() 
      });
    }

    // Sample users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple filtering based on query parameters
    let filteredUsers = users;

    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply limit and offset if provided
    const limit = req.query.limit ? parseInt(req.query.limit) : filteredUsers.length;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      totalCount: filteredUsers.length,
      limit: limit,
      offset: offset
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  const status = error.status || 500;
  const message = status === 500 ? 'Internal server error' : error.message;

  res.status(status).json({
    status: 'error',
    message: message
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server...');
  server.close(() => {
    console.log('Server closed');
  });
});

module.exports = app;

