const express = require('express');
const helmet = require('helmet');
const rateLimit = require('rate-limit');
const cors = require('cors');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// CORS configuration
app.use(cors({
  origin: process.env.WHITELISTED_DOMAINS || '*', // Configure with specific domains in production
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Input validation schema for user queries (if needed in the future)
const userQuerySchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10)
});

// Health check route with improved error handling
app.get('/health', (req, res) => {
  try {
    // In a real application, you might check database connectivity here
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users route with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    const { error: queryError, value } = userQuerySchema.validate(req.query, { abortEarly: false });

    if (queryError) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: queryError.details.map(detail => detail.message)
      });
    }

    // Extract validated parameters
    const { page, limit } = value;

    // Mock data - in a real app, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // In a real application, you would implement proper pagination
    // For now, we'll just return all users since we have a small dataset
    res.json({
      data: allUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limit)
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details
    });
  }

  // Default to generic error message
  res.status(500).json({ 
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle process termination
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

